        gangs = list(map(int, input().split()))

        graph = defaultdict(list)
        gang_districts = defaultdict(list)

        for i, gang in enumerate(gangs):
            gang_districts[gang].append(i + 1)

        if len(gang_districts) <= 1:
            print("NO")
            continue

        gangs = list(gang_districts.keys())
        for i in range(len(gangs) - 1):
            graph[gangs[i]].append(gangs[i+1])
            graph[gangs[i+1]].append(gangs[i])

        roads = []
        visited = set()

        def dfs(node):
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    roads.append((gang_districts[node][0], gang_districts[neighbor][0]))
                    dfs(neighbor)

        dfs(gangs[0])

        if len(visited) < len(gangs):
            print("NO")
        else:
            print("YES")
            for road in roads:
                print(f"{road[0]} {road[1]}")

